/*************************************************************************
*   Abort Read Command from Window					 *
*************************************************************************/

int abort_read_command(int ioid)
    /* + io device id */
{
    register IO_BACKET *it;
    register CELL *undef;
    it = &io_table[ioid];
    remove_suspended_goals(it->inp_hook);
    reset_var_table(it);
    it->kb_req = 0;
    it->ts_stt = TS_NORMAL;
    AllocUndef(undef);
    SetAll(it->inp_hook, REF, undef, MRBOFF);
    return(IOSUB_SUCCESS);
}

static int remove_suspended_goals(CELL *cc)
{
    register SUSPENSION_RECORD *srec;
    register GOAL_RECORD *grec;
    CELL *c;
    CELL tmpc;

    Dereference2(cc, c);
    do{
	if(Typeof(c) == HOOK){	/* case of single waiting */
	    grec = Goalof(c);
	    tmpc = grec->pt; c = &tmpc;
	    FreeGoalRecord(grec, grec->argn);
	}else if(Typeof(c) == MHOOK){	/* case of multiple waiting */
	    SUSPENSION_RECORD  *other;
	    srec = Suspof(c);
	    other = SrecOf(srec->other);
	    if(other == srec){
		grec = GrecOf(srec->suspended);
		FreeGoalRecord(grec, grec->argn);
	    }else{
		while(SrecOf(other->other) != srec){
		    other = SrecOf(other->other);
		}
		other->other = srec->other;
	    }
	    FreeSuspensionRecord(srec);
	    c = &(srec->forward);
	}
    }while(Typeof(c) != UNDEF);
    return 0;
}


/*************************************************************************
*   Read Character							 *
*************************************************************************/

int read_char(int ioid, int *chr)
    /* + io device id */
    /* - character code */
{
    register IO_BACKET *it;
    register int ch;
    it = &io_table[ioid];
    if(IsWindow(it) && use_windows){
	if(!request_keyboard(it)) return(IOSUB_CONTINUE);
    }
    ch = GetC(it);
    *chr = ch;
    return(ch == EOF ? IOSUB_END_OF_FILE : IOSUB_SUCCESS);
}


/*************************************************************************
*   Read Line								 *
*************************************************************************/

int read_line(int ioid, CELL *line)
    /* + io device id */
    /* - line (STRING) */
{
    register IO_BACKET *it;
    register int ch = 0;	/* MODERN: was read uninitialised on a resume */
    it = &io_table[ioid];
    if(it->ts_stt != TS_LINE){
	if(IsWindow(it) && use_windows){
	    if(!request_keyboard(it)) return(IOSUB_CONTINUE);
	}
	ClearTSB(it);
	while((ch = GetC(it)) != '\n' && ch != EOF) PutTSB(ch, it);
	if(HeapRest() <= (it->ts_ptr-it->ts_buf)/4){  /* Redo after GC */
	    it->ts_stt = TS_LINE;
	    SetHeapGcFlag();
	    return(IOSUB_REQUEST_GC);
	}
    }
    it->ts_stt = TS_NORMAL;
    SetAll(line, STRING,
	   convert_to_kl1_string2(it->ts_buf, it->ts_ptr-it->ts_buf), MRBOFF);
    return(ch == EOF ? IOSUB_END_OF_FILE : IOSUB_SUCCESS);
}


/*************************************************************************
*   Read Buffer								 *
*************************************************************************/

int read_buffer(int ioid, int max, CELL *buf)
    /* + io device id */
    /* + maximun size of buffer */
    /* - line (STRING) */
{
    register IO_BACKET *it;
    register int ch = 0;	/* MODERN: was read uninitialised when max <= 0 */
    if(HeapRest() <= max/4){  /* Redo after GC */
	SetHeapGcFlag();
	return(IOSUB_REQUEST_GC);
    }
    it = &io_table[ioid];
    if(IsWindow(it)){
	if(use_windows){
	    if(!request_keyboard(it)) return(IOSUB_CONTINUE);
	}
	ClearTSB(it);
	while(max-- > 0 && (ch = GetC(it)) != EOF){
	    PutTSB(ch, it);
	    if(ch == '\n') break;
	}
    }else{
	ClearTSB(it);
	while(max-- > 0 && (ch = getc(it->in)) != EOF){
	    PutTSB(ch, it);
	}
    }
    SetAll(buf, STRING,
	   convert_to_kl1_string2(it->ts_buf, it->ts_ptr-it->ts_buf), MRBOFF);
    return(ch == EOF ? IOSUB_END_OF_FILE : IOSUB_SUCCESS);
}


/*************************************************************************
*   Token Scanner							 *
*************************************************************************/

#define	 SCAN_SUCCESS	0
#define	 SCAN_CONTINUE	1
#define	 SCAN_ERROR    -1


/*************************************************************************
*   Macros to Make Token List						 *
*************************************************************************/

#define MakeAtomToken(head, atom){\
    AllocCons(cons);\
    AllocVector2(vect, 2);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    if((chr2 = GetC(it)) == '('){\
	vect[1] = const_atom_open;\
    }else{\
	UnGetC(chr2, it);\
	vect[1] = const_atom_atom;\
    }\
    SetAll(&vect[2], ATOM, atom, MRBOFF);\
    head = &cons[1];\
}

#define MakeSignToken(head, atom){\
    AllocCons(cons);\
    AllocVector2(vect, 2);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    vect[1] = const_atom_sign;\
    SetAll(&vect[2], ATOM, atom, MRBOFF);\
    head = &cons[1];\
}

#define MakeIntegerToken(head, integer){\
    AllocCons(cons);\
    AllocVector2(vect, 2);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    vect[1] = const_atom_integer;\
    SetAll(&vect[2], INT, integer, MRBOFF);\
    head = &cons[1];\
}

#define MakeFloatToken(head, flot){\
    AllocCons(cons);\
    AllocVector2(vect, 2);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    vect[1] = const_atom_float;\
    SetAll(&vect[2], FLOAT, flot, MRBOFF);\
    head = &cons[1];\
}

#define MakeStringToken(head, string){\
    AllocCons(cons);\
    AllocVector2(vect, 2);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    vect[1] = const_atom_string;\
    SetAll(&vect[2], STRING, string, MRBOFF);\
    head = &cons[1];\
}

#define MakeVarToken(head, number, string){\
    AllocCons(cons);\
    AllocVector2(vect, 3);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    vect[1] = const_atom_d_var;\
    SetAll(&vect[2], INT, number, MRBOFF);\
    SetAll(&vect[3], STRING, string, MRBOFF);\
    head = &cons[1];\
}

#define MakeSpecialToken(head, atom){\
    AllocCons(cons);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], ATOM, atom, MRBOFF);\
    head = &cons[1];\
}

#define MakeIllegalToken(head, string){\
    AllocCons(cons);\
    AllocVector2(vect, 2);\
    SetAll(head, LIST, cons, MRBOFF);\
    SetAll(&cons[0], VECTOR, vect, MRBOFF);\
    vect[1] = const_atom_illegal;\
    SetAll(&vect[2], STRING, string, MRBOFF);\
    head = &cons[1];\
}

#define ContinueTokenList(head, tail){\
    AllocUndef(vect);\
    SetAll(head, REF, vect, MRBOFF);\
    SetAll(tail, REF, vect, MRBOFF);\
}

#define CloseTokenList(head){\
    AllocCons(cons);\
    SetAll(head, LIST, cons, MRBOFF);\
    cons[0] = const_atom_end;\
    cons[1] = const_nil;\
}


/*************************************************************************
*   Read Token								 *
*************************************************************************/

int read_token(int ioid, register CELL *head, CELL *tail, int *vars)
    /* + io device id */
    /* - token list head (REF=>UNDEF or LIST or NIL) */
    /* - token list tail (REF=>UNDEF or NIL) */
    /* - number of variable */
{
    register IO_BACKET *it;
    register CELL *cons, *vect;
    register int chr, chr2, sign;
    int32_t x;

    it = &io_table[ioid];
    if(IsWindow(it) && use_windows){
	if(!request_keyboard(it)){
	    ContinueTokenList(head, tail);
	    return(IOSUB_CONTINUE);  /** Date is Not Ready **/
	}
    }
    switch(it->ts_stt){
      case TS_QATOM:
	switch(scan_quote_atom(it)){
	  case SCAN_SUCCESS:
	    MakeAtomToken(head, intern_atom(it->ts_buf));
	    it->ts_stt = TS_NORMAL;
	    break;
	  case SCAN_CONTINUE:
	    ContinueTokenList(head, tail);
	    return(IOSUB_CONTINUE);
	  case SCAN_ERROR:
	    CloseTokenList(head);
	    *vars = reset_var_table(it);
	    it->ts_stt = TS_NORMAL;
	    return(IOSUB_EOF_IN_QUOTE);
	}
	break;
      case TS_STRING:
	switch(scan_string(it)){
	  case SCAN_SUCCESS:
	    MakeStringToken(head, convert_to_kl1_string(it->ts_buf));
	    it->ts_stt = TS_NORMAL;
	    break;
	  case SCAN_CONTINUE:
	    ContinueTokenList(head, tail);
	    return(IOSUB_CONTINUE);
	  case SCAN_ERROR:
	    CloseTokenList(head);
	    *vars = reset_var_table(it);
	    it->ts_stt = TS_NORMAL;
	    return(IOSUB_EOF_IN_QUOTE);
	}
	break;
      case TS_COMMENT:
	switch(scan_comment(it)){
	  case SCAN_SUCCESS:
	    it->ts_stt = TS_NORMAL;
	    break;
	  case SCAN_CONTINUE:
	    ContinueTokenList(head, tail);
	    return(IOSUB_CONTINUE);
	  case SCAN_ERROR:
	    CloseTokenList(head);
	    *vars = reset_var_table(it);
	    it->ts_stt = TS_NORMAL;
	    return(IOSUB_END_OF_FILE);
	}
	break;
    }

    for(;;){
	if(GcFlag_ON()){    /******** Check GC Request ********/
	    ContinueTokenList(head, tail);
	    return(IOSUB_REQUEST_GC);
	}
	chr = GetC(it);
	if(chr == EOF) goto eof_in_term;
	while(IsBlank(chr)){	   /******** Skip Blank ********/
	    if(chr == '\n'){
		if(IsWindow(it) && use_windows){
		    if(!request_keyboard(it)){
			ContinueTokenList(head, tail);
			return(IOSUB_CONTINUE);	 /** Date is Not Ready **/
		    }
		}
	    }
	    chr = GetC(it);
	    if(chr == EOF) goto eof_in_term;
	}
	if(chr == '%'){		 /******** Skip Comment ********/
	    while((chr = GetC(it)) != '\n'){
		if(chr == EOF) goto eof_in_term;
	    }
	    if(IsWindow(it) && use_windows){
		if(!request_keyboard(it)){
		    ContinueTokenList(head, tail);
		    return(IOSUB_CONTINUE);  /** Date is Not Ready **/
		}
	    }
	    continue;
	}
	if(chr == '/'){
	    chr2 = GetC(it);
	    if(chr2 == EOF) goto eof_in_term;
	    UnGetC(chr2, it);
	    if(chr2 == '*'){
		switch(scan_comment(it)){
		  case SCAN_SUCCESS:
		    continue;
		  case SCAN_CONTINUE:
		    ContinueTokenList(head, tail);
		    it->ts_stt = TS_COMMENT;
		    return(IOSUB_CONTINUE);
		  case SCAN_ERROR:
		    CloseTokenList(head);
		    *vars = reset_var_table(it);
		    return(IOSUB_END_OF_FILE);
		}
	    }
	}else if(chr == '.'){	      /******** Check Full Stop ********/
  period:
	    chr2 = GetC(it);
	    if(chr2 == EOF){
  eof_in_term:
		CloseTokenList(head);
		*vars = reset_var_table(it);
		return(IOSUB_END_OF_FILE);
	    }
	    if(IsBlank(chr2)){
		CloseTokenList(head);
		*vars = reset_var_table(it);
		return(IOSUB_SUCCESS);
	    }
	    UnGetC(chr2, it);
	}else if(chr == '+'){	      /******** Check Sign ********/
	    chr2 = GetC(it);
	    if(IsDigit(chr2)){
		sign = ATOM_PLUS;
		chr = chr2;
		goto number;
	    }
	    UnGetC(chr2, it);
	}else if(chr == '-'){
	    chr2 = GetC(it);
	    if(IsDigit(chr2)){
		sign = ATOM_MINUS;
		chr = chr2;
		goto number;
	    }
	    UnGetC(chr2, it);
	}else if(chr == '$'){	      /******** Special ********/
	    chr2 = GetC(it);
	    UnGetC(chr2, it);
	    if(IsAlNum(chr2)){
		scan_alpha_atom(chr, it);
		MakeIllegalToken(head, convert_to_kl1_string(it->ts_buf));
		continue;
	    }
	}

	switch(GetCharType(chr)){
	  case DIGIT:
	    sign = 0;
  number:
	    switch(scan_integer_or_float(sign, chr, it)){
	      case 0:
		if(!conv_to_integer(sign, it->ts_buf, &x)) goto illegal_number;
		if(sign) MakeSignToken(head, sign);
		MakeIntegerToken(head, x);
		continue;
	      case 1:
		if(conv_to_integer(sign, it->ts_buf, &x)){
		    if(sign) MakeSignToken(head, sign);
		    MakeIntegerToken(head, x);
		}else{
		    if(sign) MakeAtomToken(head, sign);
		    MakeIllegalToken(head, convert_to_kl1_string(it->ts_buf));
		}
		chr = '.';
		goto period;
	      case 2:
		if(!string_to_float(it->ts_buf, &x)) goto illegal_number;
		if(sign) MakeSignToken(head, sign);
		MakeFloatToken(head, x);
		continue;
	      case 3:
	      illegal_number:
		if(sign) MakeAtomToken(head, sign);
		MakeIllegalToken(head, convert_to_kl1_string(it->ts_buf));
		continue;
	    }
	  case UPPER_CASE:
	    scan_variable(chr, it);
	    MakeVarToken(head, conv_to_var(it->ts_buf, it),
			       convert_to_kl1_string(it->ts_buf));
	    continue;
	  case LOWER_CASE:
	    scan_alpha_atom(chr, it);
	    MakeAtomToken(head, intern_atom(it->ts_buf));
	    continue;
	  case SYMBOL:
	    scan_symbol_atom(chr, it);
	    MakeAtomToken(head, intern_atom(it->ts_buf));
	    continue;
	  default:
	    switch(chr){
	      case ',':
		MakeSpecialToken(head, ATOM_COMMA);
		continue;
	      case '|':
		MakeSpecialToken(head, ATOM_VLINE);
		continue;
	      case '!':
		MakeAtomToken(head, ATOM_EXCLAMATION);
		continue;
	      case '(':
		MakeSpecialToken(head, ATOM_PAREN_L);
		continue;
	      case ')':
		MakeSpecialToken(head, ATOM_PAREN_R);
		continue;
	      case '[':
		if((chr = GetC(it)) == ']'){
		    MakeAtomToken(head, NIL);
		    continue;
		}else{
		    UnGetC(chr, it);
		    MakeSpecialToken(head, ATOM_BRANKET_L);
		    continue;
		}
	      case ']':
		MakeSpecialToken(head, ATOM_BRANKET_R);
		continue;
	      case '{':
		MakeSpecialToken(head, ATOM_BRACE_L);
		continue;
	      case '}':
		MakeSpecialToken(head, ATOM_BRACE_R);
		continue;
	      case '\'':
		ClearTSB(it);
		switch(scan_quote_atom(it)){
		  case SCAN_SUCCESS:
		    MakeAtomToken(head, intern_atom(it->ts_buf));
		    continue;
		  case SCAN_CONTINUE:
		    ContinueTokenList(head, tail);
		    it->ts_stt = TS_QATOM;
		    return(IOSUB_CONTINUE);
		  case SCAN_ERROR:
		    CloseTokenList(head);
		    *vars = reset_var_table(it);
		    return(IOSUB_EOF_IN_QUOTE);
		}
	      case '"':
		ClearTSB(it);
		switch(scan_string(it)){
		  case SCAN_SUCCESS:
		    MakeStringToken(head, convert_to_kl1_string(it->ts_buf));
		    continue;
		  case SCAN_CONTINUE:
		    ContinueTokenList(head, tail);
		    it->ts_stt = TS_STRING;
		    return(IOSUB_CONTINUE);
		  case SCAN_ERROR:
		    CloseTokenList(head);
		    *vars = reset_var_table(it);
		    return(IOSUB_EOF_IN_QUOTE);
		}
	    }
	}
    }
}


/*************************************************************************
*   Scan Token Subroutine -- Integer/Float				 *
*************************************************************************/

static int scan_integer_or_float(int sign, register int chr, register IO_BACKET *it)
{
    register unsigned int base, f;
    ClearTSB(it);
    PutTSB(chr, it);
    base = (unsigned int)GetDigitValue(chr);
    chr = GetC(it);
    while(IsDigit(chr)){
	base = (base*10)+(unsigned int)GetDigitValue(chr);
	PutTSB(chr, it);
	chr = GetC(it);
    }
    if(chr == '\''){
	PutTSB(chr, it);
	chr = GetC(it);
	if(!IsAlNum(chr)){
	    UnGetC(chr, it);
	    PutTSB(0, it);
	    return(3);
	}
	PutTSB(chr, it);
	chr = GetC(it);
	while(IsAlNum(chr)){
	    PutTSB(chr, it);
	    chr = GetC(it);
	}
	UnGetC(chr, it);
	PutTSB(0, it);
	return(sign ? 3 : 0);
    }else if(chr == '.'){
	chr = GetC(it);
	if(!IsDigit(chr)){
	    UnGetC(chr, it);
	    PutTSB(0, it);
	    return(1);
	}
	PutTSB('.', it);
	while(IsDigit(chr)){
	    PutTSB(chr, it);
	    chr = GetC(it);
	}
	f = YES;
	if(chr == 'e' || chr == 'E'){
	    PutTSB(chr, it);
	    chr = GetC(it);
	    if(chr == '+' || chr == '-'){
		PutTSB(chr, it);
		chr = GetC(it);
	    }
	    if(IsDigit(chr)){
		while(IsDigit(chr)){
		    PutTSB(chr, it);
		    chr = GetC(it);
		}
	    }else if(!IsAlpha(chr)){
		UnGetC(chr, it);
		PutTSB(0, it);
		return(3);
	    }
	}
	if(IsAlNum(chr)){
	    f = NO;
	    while(IsAlNum(chr)){
		PutTSB(chr, it);
		chr = GetC(it);
	    }
	}
	UnGetC(chr, it);
	PutTSB(0, it);
	return(f ? 2 : 3);
    }else{
	f = YES;
	if(IsAlNum(chr)){
	    f = NO;
	    while(IsAlNum(chr)){
		PutTSB(chr, it);
		chr = GetC(it);
	    }
	}
	UnGetC(chr, it);
	PutTSB(0, it);
	return(f ? 0 : 3);
    }
}

static int conv_to_integer(int sign, register CHAR *c, uint32_t *x)
{
    register int base;
    double value;
    value = 0.0;
    switch(sign){
      case 0:
	while(IsDigit(*c)){
	    value = value*10.0+(double)GetDigitValue(*c++);
	    if(IntOverflowP(value)) return(NO);
	}
	if(*c == '\''){
	    if(value < 2.0 || value > 36.0) return(NO);
	    base = (int)value;
	    value = 0.0;
	    c++;
	    while(IsAlNum(*c)){
		if(GetDigitValue(*c) == 0xFF || GetDigitValue(*c) >= base)
		    return(NO);
		value = value*(double)base+(double)GetDigitValue(*c++);
		if(IntOverflowU(value)) return(NO);
	    }
	}
	break;
      case ATOM_PLUS:
	while(IsDigit(*c)){
	    value = value*10.0+(double)GetDigitValue(*c++);
	    if(IntOverflowP(value)) return(NO);
	}
	break;
      case ATOM_MINUS:
	while(IsDigit(*c)){
	    value = value*10.0+(double)GetDigitValue(*c++);
	    if(IntOverflowM(value)) return(NO);
	}
	break;
    }
    *x = (unsigned int)value;
    return(YES);
}


/*************************************************************************
*   Scan Token Subroutine -- Variable/Atom				 *
*************************************************************************/

static int scan_variable(register int chr, register IO_BACKET *it)
{
    ClearTSB(it);
    PutTSB(chr, it);
    chr = GetC(it);
    while(IsAlNum(chr)){ PutTSB(chr, it); chr = GetC(it); }
    UnGetC(chr, it);
    PutTSB(0, it);
    return 0;
}

