/*************************************************************************
*   Scan Token Subroutine -- Quoted Object				 *
*************************************************************************/

static int scan_quote_atom(register IO_BACKET *it)
{
    register int chr;
    for(;;){
	chr = GetC(it);
	if(chr == EOF){
	    return(SCAN_ERROR);
	}else if(chr == '\n' && IsWindow(it)){
	    if(!request_keyboard(it)){
		PutTSB(chr, it);
		return(SCAN_CONTINUE);	/** Date is Not Ready **/
	    }
	}else if(chr == '\''){
	    if((chr = GetC(it)) != '\''){
		UnGetC(chr, it);
		PutTSB(0, it);
		return(SCAN_SUCCESS);
	    }
	}
	PutTSB(chr, it);
    }
}

static int scan_string(register IO_BACKET *it)
{
    register int chr;
    for(;;){
	chr = GetC(it);
	if(chr == EOF){
	    return(SCAN_ERROR);
	}else if(chr == '\n' && IsWindow(it)){
	    if(!request_keyboard(it)){
		PutTSB(chr, it);
		return(SCAN_CONTINUE);	/** Date is Not Ready **/
	    }
	}else if(chr == '"'){
	    if((chr = GetC(it)) != '"'){
		UnGetC(chr, it);
		PutTSB(0, it);
		return(SCAN_SUCCESS);
	    }
	}
	PutTSB(chr, it);
    }
}

static int scan_comment(register IO_BACKET *it)
{
    register int chr;
    chr = GetC(it);
    for(;;){
	if(chr == EOF){
	    return(SCAN_ERROR);
	}else if(chr == '\n' && IsWindow(it)){
	    if(!request_keyboard(it)){
		return(SCAN_CONTINUE);	/** Date is Not Ready **/
	    }
	}else if(chr == '*'){
	    if((chr = GetC(it)) == '/'){
		return(SCAN_SUCCESS);
	    }
	}else{
	    chr = GetC(it);
	}
    }
}


/*************************************************************************
*   Token Scanner Buffer Support					 *
*************************************************************************/

static int expand_ts_buffer(register IO_BACKET *it)
{
    register int siz, i;
    register CHAR *old, *new;
    old = it->ts_buf;
    siz = it->ts_siz;
    new = malloc(siz*2);
    if(new == NULL){
	Error("Not Enough Memory (malloc failure) -- Aborted.");
	exit_pdss(1);
    }
    memmove(new, old, siz);
    free(old);
    siz *= 2;
    if(IsWindow(it)){
	it->ts_buf = new;
	it->ts_siz = siz;
    }else{
	for(i = MAX_OF_WINDOW; i < MAX_OF_WINDOW+MAX_OF_FILE; i++){
	    io_table[i].ts_buf = new;
	    io_table[i].ts_siz = siz;
	}
    }
    it->ts_ptr = new+(it->ts_ptr-old);
    return 0;
}


/*************************************************************************
*   Variable Table							 *
*************************************************************************/

static int reset_var_table(register IO_BACKET *it)
{
    register int i;
    for(i=0; i<VT_HASH; i++) it->var[i] = NULL;
    i = it->var_num;
    it->var_num = 0;
    it->vt_ptr = it->vt_mem;
    return(i);
}

static VAR_ENTRY *alloc_var_table(int size, IO_BACKET *it)
{
    register CHAR *p, *q;
    CHAR *buf;
    VAR_ENTRY **v;
    int offset, i;
    size += sizeof(VAR_ENTRY);
    size = (size+(int)_Alignof(VAR_ENTRY)-1) & ~((int)_Alignof(VAR_ENTRY)-1);	/* MODERN: was 4 */
    while(it->vt_ptr+size > it->vt_mem+it->vt_siz){
	buf = malloc(it->vt_siz*2);
	if(buf == NULL){
	    Error("Not Enough Memory (malloc failure) -- Aborted.");
	    exit_pdss(1);
	}
	p = it->vt_mem; q = buf;
	offset = q-p;
	while(p < it->vt_ptr) *q++ = *p++;
	for(i=0; i<VT_HASH; i++){
	    v = &(it->var[i]);
	    while(*v){
		*v = (VAR_ENTRY *)((CHAR *)(*v)+offset);
		v = &((*v)->next);
	    }
	}
	free(it->vt_mem);
	it->vt_mem = buf;
	it->vt_ptr += offset;
	it->vt_siz *= 2;
    }
    p = it->vt_ptr;
    it->vt_ptr += size;
    return((VAR_ENTRY *)p);
}

static int conv_to_var(CHAR *name, IO_BACKET *it)
{
    register VAR_ENTRY *p;
    register int hash;
    register CHAR *s;
    if(name[0]=='_' && name[1]==0) return(it->var_num++);
    s = name;
    hash = 0;
    while(*s) hash = (hash*37 + *s++)&(VT_HASH-1);
    for(p = it->var[hash]; p != NULL; p = p->next){
	if(strcmp(name, p->name) == 0) return(p->number);
    }
    p = alloc_var_table(strlen(name), it);
    p->number = it->var_num++;
    strcpy(p->name, name);
    p->next = it->var[hash];
    it->var[hash] = p;
    return(p->number);
}
